const fs = require('fs');
const path = require('path');

const manifestsDir = path.resolve(__dirname, '../manifests');

// 1. Read existing SeDev items (from manifests/*.json or generate_sedev_tech_pieces logic)
// To ensure clean data, read the 21 SeDev items
const sedevFiles = fs.readdirSync(manifestsDir)
  .filter(f => f.startsWith('sedev_') && f.endsWith('.json'))
  .sort();

// Also check if current bundle has scripts attached
const currentBundlePath = path.join(manifestsDir, 'all_manifests_bundle.js');
let existingBundleSedev = [];
if (fs.existsSync(currentBundlePath)) {
  try {
    const rawCode = fs.readFileSync(currentBundlePath, 'utf8');
    const fakeWin = {};
    const evalFn = new Function('window', 'globalThis', rawCode + '; return window.__BIBLIOTECA_SEDEV__ || window.__BIBLIOTECA_2026__;');
    existingBundleSedev = evalFn(fakeWin, fakeWin) || [];
  } catch (e) {
    console.warn('Could not eval existing bundle:', e.message);
  }
}

let sedevItems = [];
if (existingBundleSedev.length >= 21) {
  sedevItems = existingBundleSedev;
} else {
  sedevItems = sedevFiles.map((f, i) => {
    const json = JSON.parse(fs.readFileSync(path.join(manifestsDir, f), 'utf8'));
    const totalDur = (json.scenes || []).reduce((acc, s) => acc + (s.duration || 5), 0);
    const numMatch = f.match(/_(\d+)_/);
    const numStr = numMatch ? numMatch[1] : (i + 1).toString().padStart(2, '0');
    return {
      key: json.slug || f.replace('.json', ''),
      num: numStr,
      slug: json.slug || f.replace('.json', ''),
      label: json.title || f,
      category: json.category || 'INGENIERÍA & LORE',
      tagline: json.tagline || '',
      script: json.script || null,
      duration: Number(totalDur.toFixed(1)),
      scenesCount: (json.scenes || []).length,
      brand: 'sedev',
      manifest: json
    };
  });
}
sedevItems.forEach(item => { item.brand = 'sedev'; });

// 2. Read Nevox items from manifests/nevox/*.json
const nevoxDir = path.join(manifestsDir, 'nevox');
const nevoxFiles = fs.readdirSync(nevoxDir).filter(f => f.endsWith('.json')).sort((a, b) => {
  const matchA = a.match(/_(\d+)_/);
  const matchB = b.match(/_(\d+)_/);
  const numA = matchA ? parseInt(matchA[1], 10) : 0;
  const numB = matchB ? parseInt(matchB[1], 10) : 0;
  return numA - numB;
});
const nevoxItems = nevoxFiles.map((f, i) => {
  const json = JSON.parse(fs.readFileSync(path.join(nevoxDir, f), 'utf8'));
  const totalDur = (json.scenes || []).reduce((acc, s) => acc + (s.duration || 5), 0);
  const numMatch = json.slug.match(/_(\d+)_/);
  const numStr = numMatch ? numMatch[1] : (i + 1).toString().padStart(2, '0');
  return {
    key: json.slug,
    num: numStr,
    slug: json.slug,
    label: json.title,
    category: json.category || json.pilar || 'AUTOMATIZACIÓN & SAAS TRAP',
    pilar: json.pilar,
    introType: json.introType || 'COST TICKER',
    ctaKeyword: json.ctaKeyword || 'SISTEMA',
    duration: Number(totalDur.toFixed(1)),
    scenesCount: (json.scenes || []).length,
    brand: 'nevox',
    manifest: json
  };
});

const fileHeader = `// Unified Video Catalog: SeDev (Tech Lore) & Nevox (B2B Convertible)
// Auto-generated by build_unified_bundle.js
(function(root) {
  var sedev = ${JSON.stringify(sedevItems, null, 2)};
  var nevox = ${JSON.stringify(nevoxItems, null, 2)};

  root.__BIBLIOTECA_SEDEV__ = sedev;
  root.__BIBLIOTECA_NEVOX__ = nevox;
  root.__BIBLIOTECA_2026__ = sedev;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { sedev: sedev, nevox: nevox };
  }
})(typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this));
`;

fs.writeFileSync(path.join(manifestsDir, 'all_manifests_bundle.js'), fileHeader, 'utf8');
console.log(`✓ Bundle generado con éxito: ${sedevItems.length} piezas SeDev y ${nevoxItems.length} piezas Nevox.`);
